xml.Script:
        
        function IntToHex1(num);
        begin
            case (num) of
                10: Result := 'A';
                11: Result := 'B';
                12: Result := 'C';
                13: Result := 'D';
                14: Result := 'E';
                15: Result := 'F';
            else
                Result := IntToStr(num);
            end;
        end;

        
        function IntToHex2(num);
        begin
            Result := IntToHex1(num div 16) + IntToHex1(num mod 16);
        end;

        function RGB( R, G, B);
        begin
            Result := IntToHex2(int(255 * R)) + IntToHex2(int(255 * G)) + IntToHex2(int(255 * B));
        end;

        
        
        function HSVToHex(H, S, V);
        begin
            
            H := H - int(H);

            if not (S = 0) then begin // non-zero Saturation
                vh := H * 6;
                vi := int(vh);
                v1 := V * (1 - S);
                v2 := V * (1 - S * (vh - vi));
                v3 := V * (1 - S * (1 - (vh - vi)));

                case (vi) of
                    0 : RGB(  V, v3, v1);
                    1 : RGB( v2,  V, v1);
                    2 : RGB( v1,  V, v3);
                    3 : RGB( v1, v2,  V);
                    4 : RGB( v3, v1,  V);
                    5 : RGB(  V, v1, v2);
                end;
            end else
                RGB( V, V, V);
        end;

        N := 11;
        for i := 0 to N - 1 do begin
             Colors[i, 0] := HSVToHex(i/N, 1.00, 0.87);
             Colors[i, 1] := HSVToHex(i/N, 0.75, 1.00);
        end;

        R := 0.6;
        Spiral := 0.2;
        NR := 70 div N; // sides per tooth
        H  := R * 0.25;
        H1 := H * 1.005;

        // sticker parameters
        WA := 0.79;
        R2 := R * 0.95;
        R1 := R * 0.76;

        Angle := 2 * Pi / N;
        D  := R * sin(Angle / 4);
        H2 := H1 + (H1 - H);

        for i := 0 to NR do begin
            ac := i / NR * Angle;
            sc := sin(ac);
            cc := cos(ac);

            // spiral coordinates
            x[i] := R * Exp(i / NR * Spiral) * sc;
            y[i] := R * Exp(i / NR * Spiral) * cc;

            // side sticker coordinates
            xc1[i] := R1 * sc;
            yc1[i] := R1 * cc;
            xc2[i] := R2 * sc;
            yc2[i] := R2 * cc;
        end;

        function FromTo(iFrom, iTo);
        begin
            Result := IntToStr(iFrom);
            for i := iFrom + 1 to iTo do
                Result := Result + ';' + IntToStr(i);
            for i := iFrom - 1 downto iTo do
                Result := Result + ';' + IntToStr(i);
        end;

